import re


def parse_range_list(s: str) -> list[int]:
    """Parse a comma-separated list of non-negative integers and ranges

    into a sorted list of unique integers.
    """
    s = s.strip()
    if not s:
        return []

    collected: set[int] = set()
    digit_pattern = re.compile(r"^[0-9]+$")

    for raw_item in s.split(","):
        item = raw_item.strip()
        if not item:
            raise ValueError(f"Empty item found in input: {s!r}")

        parts = item.split("-")
        if len(parts) == 1:
            val_str = parts[0].strip()
            if not digit_pattern.match(val_str):
                raise ValueError(f"Invalid integer: {item!r}")
            collected.add(int(val_str))
        elif len(parts) == 2:
            start_str, end_str = parts[0].strip(), parts[1].strip()
            if not (
                digit_pattern.match(start_str) and digit_pattern.match(end_str)
            ):
                raise ValueError(
                    f"Invalid range or negative integer: {item!r}"
                )

            start, end = int(start_str), int(end_str)
            if start > end:
                raise ValueError(
                    f"Range start cannot exceed end: {start} > {end}"
                )

            collected.update(range(start, end + 1))
        else:
            raise ValueError(f"Malformed range syntax: {item!r}")

    return sorted(collected)
```

### Component Integration Details

- **Splitting & Blank Input**: Empty or whitespace-only inputs return `[]` via `s.strip() == ""`. Splitting `"1,,2"` produces an empty item, raising `ValueError`.
- **Validation**: Strict ASCII matching (`^[0-9]+$`) ensures only valid non-negative integers are processed, rejecting `"1.5"`, `"abc"`, and `"1-"`. Inputs with negative signs (such as `'-1'`, `'-2-5'`, or `'2--3'`) produce leading empty tokens or $>2$ tokens when split on `'-'`, raising `ValueError`. Inverted ranges (`start > end`) raise `ValueError`.
- **Expansion & Result**: Ranges are inclusively expanded using `range(start, end + 1)` (per Python's standard `range` definition). A `set` provides $O(1)$ average insertion and deduplication, and `sorted()` produces the ordered list.

